CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Public handle used in the URL.
	"username" VARCHAR(24) NOT NULL UNIQUE,
	-- Free-text name shown above the handle.
	"display_name" VARCHAR(60) NOT NULL,
	-- Short profile text.
	"bio" VARCHAR(80),
	-- Private accounts are excluded from the recommendation feed entirely, not merely filtered from it at render time.
	"is_private" BOOLEAN NOT NULL DEFAULT false,
	-- Denormalised inbound follow count.
	"follower_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised outbound follow count.
	"following_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised count of live videos.
	"video_count" INTEGER NOT NULL DEFAULT 0,
	-- Lifetime likes across every video, the number on the profile header. Bigint because a single creator can pass two billion.
	"total_like_count" BIGINT NOT NULL DEFAULT 0,
	-- Signup time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A creator and a viewer in one row - the product does not separate them, and neither does the schema.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."username" IS 'Public handle used in the URL.';
COMMENT ON COLUMN "users"."display_name" IS 'Free-text name shown above the handle.';
COMMENT ON COLUMN "users"."bio" IS 'Short profile text.';
COMMENT ON COLUMN "users"."is_private" IS 'Private accounts are excluded from the recommendation feed entirely, not merely filtered from it at render time.';
COMMENT ON COLUMN "users"."follower_count" IS 'Denormalised inbound follow count.';
COMMENT ON COLUMN "users"."following_count" IS 'Denormalised outbound follow count.';
COMMENT ON COLUMN "users"."video_count" IS 'Denormalised count of live videos.';
COMMENT ON COLUMN "users"."total_like_count" IS 'Lifetime likes across every video, the number on the profile header. Bigint because a single creator can pass two billion.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time.';

CREATE TABLE IF NOT EXISTS "sounds" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Sound name shown on the sound page and on the spinning disc.
	"title" VARCHAR(200) NOT NULL,
	-- Rights holder or original creator name. Free text, because licensed catalogue and user-recorded audio do not share an identity space.
	"artist_name" VARCHAR(160),
	-- original | licensed. Original sounds are extracted from a user video, licensed ones come from a catalogue deal, and only the second kind is subject to takedown by a label.
	"kind" VARCHAR(12) NOT NULL DEFAULT 'original',
	-- Video the audio was first extracted from, for original sounds. Nullable and written after that video exists, which is what breaks the otherwise circular dependency with videos.
	"original_video_id" BIGINT,
	-- Full length of the track. A video may use any window of it.
	"duration_ms" INTEGER NOT NULL,
	-- Object-store key of the audio, referenced by every video that uses the sound rather than copied into each.
	"storage_key" VARCHAR(400) NOT NULL,
	-- Denormalised number of videos using this sound. The single most important ranking signal on the sound page and the basis of the trending-sounds chart.
	"use_count" BIGINT NOT NULL DEFAULT 0,
	-- Cleared when audio is pulled for rights reasons. Videos keep the reference and mute, rather than being deleted.
	"is_available" BOOLEAN NOT NULL DEFAULT true,
	-- When the sound first appeared.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "sounds" IS 'The reusable unit of the product. Audio is a first-class row shared by every video that uses it, which is what makes "watch the other 480,000 videos using this sound" a foreign key lookup instead of an audio-fingerprinting job.';
COMMENT ON COLUMN "sounds"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "sounds"."title" IS 'Sound name shown on the sound page and on the spinning disc.';
COMMENT ON COLUMN "sounds"."artist_name" IS 'Rights holder or original creator name. Free text, because licensed catalogue and user-recorded audio do not share an identity space.';
COMMENT ON COLUMN "sounds"."kind" IS 'original | licensed. Original sounds are extracted from a user video, licensed ones come from a catalogue deal, and only the second kind is subject to takedown by a label.';
COMMENT ON COLUMN "sounds"."original_video_id" IS 'Video the audio was first extracted from, for original sounds. Nullable and written after that video exists, which is what breaks the otherwise circular dependency with videos.';
COMMENT ON COLUMN "sounds"."duration_ms" IS 'Full length of the track. A video may use any window of it.';
COMMENT ON COLUMN "sounds"."storage_key" IS 'Object-store key of the audio, referenced by every video that uses the sound rather than copied into each.';
COMMENT ON COLUMN "sounds"."use_count" IS 'Denormalised number of videos using this sound. The single most important ranking signal on the sound page and the basis of the trending-sounds chart.';
COMMENT ON COLUMN "sounds"."is_available" IS 'Cleared when audio is pulled for rights reasons. Videos keep the reference and mute, rather than being deleted.';
COMMENT ON COLUMN "sounds"."created_at" IS 'When the sound first appeared.';

CREATE INDEX "idx_sounds_kind_use_count"
ON "sounds" ("kind", "use_count");

CREATE TABLE IF NOT EXISTS "videos" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Creator who published the video.
	"author_id" BIGINT NOT NULL,
	-- Sound used. Null only for a video with no audio track at all; every other video points at a shared row.
	"sound_id" BIGINT,
	-- Offset into the sound where playback begins. Storing the window instead of a trimmed copy is what keeps one audio object serving every video that uses it.
	"sound_start_ms" INTEGER NOT NULL DEFAULT 0,
	-- Caption as typed, hashtags included; the extracted tags live in video_hashtags.
	"caption" VARCHAR(2200),
	-- Object-store key of the encoded master. Renditions are addressed by convention from it.
	"storage_key" VARCHAR(400) NOT NULL,
	-- Video length, needed to turn watch time into a completion ratio.
	"duration_ms" INTEGER NOT NULL,
	-- Source video when this is a duet - the two play side by side. Null otherwise.
	"duet_of_video_id" BIGINT,
	-- Source video when this is a stitch - a clip of it is prepended. Null otherwise. Kept as a separate column from duet because the two render differently and are permissioned separately.
	"stitch_of_video_id" BIGINT,
	-- Offset into the source video where the borrowed clip begins. Null unless this is a stitch.
	"stitch_start_ms" INTEGER,
	-- Creator permission checked before a derivative video is accepted, not when one is played.
	"allow_duet" BOOLEAN NOT NULL DEFAULT true,
	-- Denormalised view total rolled up from watch_events; the raw events are far too many to count on read.
	"view_count" BIGINT NOT NULL DEFAULT 0,
	-- Denormalised like total.
	"like_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised comment total.
	"comment_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised share total, counted from client events rather than a table.
	"share_count" INTEGER NOT NULL DEFAULT 0,
	-- Publication time. Recency is a heavy input to recommendation, so this is read constantly.
	"published_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Soft delete. Duets and stitches point here, so the row survives as a tombstone.
	"deleted_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "videos" IS 'One video. Both derivative forms are self-references rather than copies, so the source keeps its attribution, its counters and its right to withdraw permission.';
COMMENT ON COLUMN "videos"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "videos"."author_id" IS 'Creator who published the video.';
COMMENT ON COLUMN "videos"."sound_id" IS 'Sound used. Null only for a video with no audio track at all; every other video points at a shared row.';
COMMENT ON COLUMN "videos"."sound_start_ms" IS 'Offset into the sound where playback begins. Storing the window instead of a trimmed copy is what keeps one audio object serving every video that uses it.';
COMMENT ON COLUMN "videos"."caption" IS 'Caption as typed, hashtags included; the extracted tags live in video_hashtags.';
COMMENT ON COLUMN "videos"."storage_key" IS 'Object-store key of the encoded master. Renditions are addressed by convention from it.';
COMMENT ON COLUMN "videos"."duration_ms" IS 'Video length, needed to turn watch time into a completion ratio.';
COMMENT ON COLUMN "videos"."duet_of_video_id" IS 'Source video when this is a duet - the two play side by side. Null otherwise.';
COMMENT ON COLUMN "videos"."stitch_of_video_id" IS 'Source video when this is a stitch - a clip of it is prepended. Null otherwise. Kept as a separate column from duet because the two render differently and are permissioned separately.';
COMMENT ON COLUMN "videos"."stitch_start_ms" IS 'Offset into the source video where the borrowed clip begins. Null unless this is a stitch.';
COMMENT ON COLUMN "videos"."allow_duet" IS 'Creator permission checked before a derivative video is accepted, not when one is played.';
COMMENT ON COLUMN "videos"."view_count" IS 'Denormalised view total rolled up from watch_events; the raw events are far too many to count on read.';
COMMENT ON COLUMN "videos"."like_count" IS 'Denormalised like total.';
COMMENT ON COLUMN "videos"."comment_count" IS 'Denormalised comment total.';
COMMENT ON COLUMN "videos"."share_count" IS 'Denormalised share total, counted from client events rather than a table.';
COMMENT ON COLUMN "videos"."published_at" IS 'Publication time. Recency is a heavy input to recommendation, so this is read constantly.';
COMMENT ON COLUMN "videos"."deleted_at" IS 'Soft delete. Duets and stitches point here, so the row survives as a tombstone.';

CREATE INDEX "idx_videos_author_published"
ON "videos" ("author_id", "published_at");
CREATE INDEX "idx_videos_sound_views"
ON "videos" ("sound_id", "view_count");
CREATE INDEX "idx_videos_duet_source"
ON "videos" ("duet_of_video_id");

CREATE TABLE IF NOT EXISTS "follows" (
	-- Account doing the following.
	"follower_id" BIGINT,
	-- Account followed.
	"followee_id" BIGINT,
	-- Per-edge push preference; a property of the relationship, not of either account.
	"notify_on_post" BOOLEAN NOT NULL DEFAULT false,
	-- When the follow started.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("follower_id", "followee_id")
);

COMMENT ON TABLE "follows" IS 'The follow graph feeds only the Following tab. The main feed does not read this table at all, which is the structural difference between this product and a feed built on who you follow.';
COMMENT ON COLUMN "follows"."follower_id" IS 'Account doing the following.';
COMMENT ON COLUMN "follows"."followee_id" IS 'Account followed.';
COMMENT ON COLUMN "follows"."notify_on_post" IS 'Per-edge push preference; a property of the relationship, not of either account.';
COMMENT ON COLUMN "follows"."created_at" IS 'When the follow started.';

CREATE INDEX "idx_follows_followee_created"
ON "follows" ("followee_id", "created_at");

CREATE TABLE IF NOT EXISTS "video_likes" (
	-- Video liked.
	"video_id" BIGINT,
	-- Account that liked it.
	"user_id" BIGINT,
	-- Like time. Also a strong positive signal, which is why the recommendation rollup reads this table as well as watch_events.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("video_id", "user_id")
);

COMMENT ON TABLE "video_likes" IS 'Explicit positive feedback. Rare compared with a watch, and weighted far more heavily because of it.';
COMMENT ON COLUMN "video_likes"."video_id" IS 'Video liked.';
COMMENT ON COLUMN "video_likes"."user_id" IS 'Account that liked it.';
COMMENT ON COLUMN "video_likes"."created_at" IS 'Like time. Also a strong positive signal, which is why the recommendation rollup reads this table as well as watch_events.';

CREATE INDEX "idx_video_likes_user_created"
ON "video_likes" ("user_id", "created_at");

CREATE TABLE IF NOT EXISTS "comments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Video being commented on, carried on replies too so a section loads in one scan.
	"video_id" BIGINT NOT NULL,
	-- Commenter.
	"author_id" BIGINT NOT NULL,
	-- Comment being replied to. Null for a top-level comment; the tree is two levels deep.
	"parent_comment_id" BIGINT,
	-- Comment text. The short limit is a product choice that keeps the overlay readable on a phone.
	"body" VARCHAR(150) NOT NULL,
	-- Denormalised like total; comment likes are not stored per row here.
	"like_count" INTEGER NOT NULL DEFAULT 0,
	-- Pinned to the top by the video author. A flag rather than a position column because only one comment can be pinned.
	"is_creator_pinned" BOOLEAN NOT NULL DEFAULT false,
	-- Posting time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "comments" IS 'Comments sorted by likes rather than time by default, which is why the index leads with like_count instead of created_at.';
COMMENT ON COLUMN "comments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "comments"."video_id" IS 'Video being commented on, carried on replies too so a section loads in one scan.';
COMMENT ON COLUMN "comments"."author_id" IS 'Commenter.';
COMMENT ON COLUMN "comments"."parent_comment_id" IS 'Comment being replied to. Null for a top-level comment; the tree is two levels deep.';
COMMENT ON COLUMN "comments"."body" IS 'Comment text. The short limit is a product choice that keeps the overlay readable on a phone.';
COMMENT ON COLUMN "comments"."like_count" IS 'Denormalised like total; comment likes are not stored per row here.';
COMMENT ON COLUMN "comments"."is_creator_pinned" IS 'Pinned to the top by the video author. A flag rather than a position column because only one comment can be pinned.';
COMMENT ON COLUMN "comments"."created_at" IS 'Posting time.';

CREATE INDEX "idx_comments_video_likes"
ON "comments" ("video_id", "like_count");

CREATE TABLE IF NOT EXISTS "watch_events" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account watching. Every row is attributable, because an anonymous watch teaches the recommender nothing.
	"viewer_id" BIGINT NOT NULL,
	-- Video watched.
	"video_id" BIGINT NOT NULL,
	-- for_you | following | sound | hashtag | profile | search. Where the impression came from, which is what lets the recommender measure itself against the other surfaces.
	"source" VARCHAR(16) NOT NULL,
	-- Milliseconds actually watched, summed across loops.
	"watched_ms" INTEGER NOT NULL,
	-- watched_ms divided by video duration, stored because it is the single best implicit signal and recomputing it means joining to videos on every read.
	"completion_ratio" REAL NOT NULL,
	-- Times the clip replayed. A second loop is a much stronger signal than a long first watch.
	"loop_count" SMALLINT NOT NULL DEFAULT 1,
	-- Set when the viewer swiped away in the first seconds. Explicit negative feedback, which a missing row could never express.
	"skipped_early" BOOLEAN NOT NULL DEFAULT false,
	-- Event time. The table is partitioned on this and old partitions are dropped, because it is orders of magnitude larger than everything else.
	"watched_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "watch_events" IS 'Append-only behavioural log, the raw material the feed is built from. Nothing in the product reads it directly: rollup jobs turn it into view counts and affinity scores, and the rows themselves age out.';
COMMENT ON COLUMN "watch_events"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "watch_events"."viewer_id" IS 'Account watching. Every row is attributable, because an anonymous watch teaches the recommender nothing.';
COMMENT ON COLUMN "watch_events"."video_id" IS 'Video watched.';
COMMENT ON COLUMN "watch_events"."source" IS 'for_you | following | sound | hashtag | profile | search. Where the impression came from, which is what lets the recommender measure itself against the other surfaces.';
COMMENT ON COLUMN "watch_events"."watched_ms" IS 'Milliseconds actually watched, summed across loops.';
COMMENT ON COLUMN "watch_events"."completion_ratio" IS 'watched_ms divided by video duration, stored because it is the single best implicit signal and recomputing it means joining to videos on every read.';
COMMENT ON COLUMN "watch_events"."loop_count" IS 'Times the clip replayed. A second loop is a much stronger signal than a long first watch.';
COMMENT ON COLUMN "watch_events"."skipped_early" IS 'Set when the viewer swiped away in the first seconds. Explicit negative feedback, which a missing row could never express.';
COMMENT ON COLUMN "watch_events"."watched_at" IS 'Event time. The table is partitioned on this and old partitions are dropped, because it is orders of magnitude larger than everything else.';

CREATE INDEX "idx_watch_events_viewer_time"
ON "watch_events" ("viewer_id", "watched_at");
CREATE INDEX "idx_watch_events_video_time"
ON "watch_events" ("video_id", "watched_at");

CREATE TABLE IF NOT EXISTS "hashtags" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Normalised lowercase tag without the #.
	"tag" VARCHAR(140) NOT NULL UNIQUE,
	-- Denormalised number of videos carrying the tag.
	"video_count" BIGINT NOT NULL DEFAULT 0,
	-- Denormalised total views across those videos, which is the number shown on the tag page.
	"view_count" BIGINT NOT NULL DEFAULT 0,
	-- First use.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "hashtags" IS 'Extracted tags. They double as the topic vocabulary the affinity table scores against, which is why they are deduplicated rows and not strings in a caption.';
COMMENT ON COLUMN "hashtags"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "hashtags"."tag" IS 'Normalised lowercase tag without the #.';
COMMENT ON COLUMN "hashtags"."video_count" IS 'Denormalised number of videos carrying the tag.';
COMMENT ON COLUMN "hashtags"."view_count" IS 'Denormalised total views across those videos, which is the number shown on the tag page.';
COMMENT ON COLUMN "hashtags"."created_at" IS 'First use.';

CREATE TABLE IF NOT EXISTS "video_hashtags" (
	-- Video carrying the tag.
	"video_id" BIGINT,
	-- Tag used.
	"hashtag_id" BIGINT,
	-- Order the tags appeared in the caption; the first tag is treated as the primary topic by the rollup.
	"position" SMALLINT NOT NULL DEFAULT 0,
	PRIMARY KEY("video_id", "hashtag_id")
);

COMMENT ON TABLE "video_hashtags" IS 'Join between videos and tags, written by the caption parser at publish time.';
COMMENT ON COLUMN "video_hashtags"."video_id" IS 'Video carrying the tag.';
COMMENT ON COLUMN "video_hashtags"."hashtag_id" IS 'Tag used.';
COMMENT ON COLUMN "video_hashtags"."position" IS 'Order the tags appeared in the caption; the first tag is treated as the primary topic by the rollup.';

CREATE INDEX "idx_video_hashtags_tag_video"
ON "video_hashtags" ("hashtag_id", "video_id");

CREATE TABLE IF NOT EXISTS "user_topic_affinity" (
	-- Viewer whose taste this describes.
	"user_id" BIGINT,
	-- Topic, reusing the hashtag vocabulary rather than inventing a second taxonomy.
	"hashtag_id" BIGINT,
	-- Decayed affinity in roughly zero to one. Recomputed from watch_events and video_likes, so it is derived data that can be rebuilt from scratch.
	"score" REAL NOT NULL DEFAULT 0,
	-- Total time spent on the topic, kept alongside the score because a score alone cannot be sanity-checked.
	"watch_seconds" INTEGER NOT NULL DEFAULT 0,
	-- Last rollup. Staleness here is visible as a feed that has stopped adapting.
	"updated_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("user_id", "hashtag_id")
);

COMMENT ON TABLE "user_topic_affinity" IS 'The materialised taste profile the feed is assembled from. It is a cache with no authority - deleting it costs a few hours of personalisation, not any user data.';
COMMENT ON COLUMN "user_topic_affinity"."user_id" IS 'Viewer whose taste this describes.';
COMMENT ON COLUMN "user_topic_affinity"."hashtag_id" IS 'Topic, reusing the hashtag vocabulary rather than inventing a second taxonomy.';
COMMENT ON COLUMN "user_topic_affinity"."score" IS 'Decayed affinity in roughly zero to one. Recomputed from watch_events and video_likes, so it is derived data that can be rebuilt from scratch.';
COMMENT ON COLUMN "user_topic_affinity"."watch_seconds" IS 'Total time spent on the topic, kept alongside the score because a score alone cannot be sanity-checked.';
COMMENT ON COLUMN "user_topic_affinity"."updated_at" IS 'Last rollup. Staleness here is visible as a feed that has stopped adapting.';

CREATE INDEX "idx_affinity_user_score"
ON "user_topic_affinity" ("user_id", "score");

CREATE TABLE IF NOT EXISTS "sound_favorites" (
	-- Sound saved.
	"sound_id" BIGINT,
	-- Creator who saved it.
	"user_id" BIGINT,
	-- When it was bookmarked, which is the order the creation tool shows them in.
	"saved_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("sound_id", "user_id")
);

COMMENT ON TABLE "sound_favorites" IS 'Creators bookmarking audio to use later. It exists because the sound, not the video, is what people want to come back to - the clearest evidence that audio deserved its own table.';
COMMENT ON COLUMN "sound_favorites"."sound_id" IS 'Sound saved.';
COMMENT ON COLUMN "sound_favorites"."user_id" IS 'Creator who saved it.';
COMMENT ON COLUMN "sound_favorites"."saved_at" IS 'When it was bookmarked, which is the order the creation tool shows them in.';

